function validate([word, k]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'word needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > word.length) return 'k must be an integer from 1 to word.length.';
  if (word.length % k !== 0) return 'k must divide the length of word.';
  return null;
}

