function minimumOperationsToMakeKPeriodic(word, k) {
  const count = new Map();
  let most = 0;
  for (let start = 0; start < word.length; start += k) {
    const block = word.slice(start, start + k);
    const seen = (count.get(block) ?? 0) + 1;
    count.set(block, seen);
    most = Math.max(most, seen);
  }
  const blocks = word.length / k;
  return blocks - most;
}

