function minimumOperationsToMakeKPeriodic(word, k) {
  // Breadth-first search over the actual operations on tiny inputs.
  const parts = [];
  for (let i = 0; i < word.length; i += k) parts.push(word.substring(i, i + k));
  const periodic = (arr) => arr.every(p => p === arr[0]);
  const key = (arr) => arr.join('|');
  let frontier = [parts];
  const visited = new Set([key(parts)]);
  for (let steps = 0; ; steps++) {
    const following = [];
    for (const state of frontier) {
      if (periodic(state)) return steps;
      for (let i = 0; i < state.length; i++)
        for (let j = 0; j < state.length; j++) {
          if (state[i] === state[j]) continue;
          const copy = state.slice();
          copy[i] = state[j];
          const id = key(copy);
          if (!visited.has(id)) { visited.add(id); following.push(copy); }
        }
    }
    frontier = following;
  }
}

