function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomBlock = (k, alphabet) => {
    let s = '';
    for (let c = 0; c < k; c++) s += letters[Math.floor(rand() * alphabet)];
    return s;
  };
  let k, blocks, alphabet, poolSize;
  if (size === 'large') {
    const choices = [1, 2, 3, 4, 5, 8, 10, 20, 50, 100];
    k = choices[Math.floor(rand() * choices.length)];
    blocks = Math.max(1, Math.floor(10000 / k) - Math.floor(rand() * 10));
    alphabet = 2 + Math.floor(rand() * 25);
    poolSize = 1 + Math.floor(rand() * 30);
  } else {
    k = 1 + Math.floor(rand() * 3);
    blocks = 1 + Math.floor(rand() * 5);
    alphabet = 1 + Math.floor(rand() * 3);
    poolSize = 1 + Math.floor(rand() * 4);
  }
  // Drawing blocks from a small pool, with a skew towards the first ones, makes repeats likely.
  const pool = Array.from({ length: poolSize }, () => randomBlock(k, alphabet));
  let word = '';
  for (let b = 0; b < blocks; b++) {
    word += pool[Math.floor(Math.pow(rand(), 2) * poolSize)];
  }
  return [word, k];
}
